  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Account {\n  id                       String  @id @default(cuid())\n  userId                   String\n  type                     String\n  provider                 String\n  providerAccountId        String\n  refresh_token            String?\n  access_token             String?\n  expires_at               Int?\n  token_type               String?\n  scope                    String?\n  id_token                 String?\n  session_state            String?\n  refresh_token_expires_in Int?\n  user                     User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel User {\n  id                   String               @id @default(cuid())\n  name                 String?\n  email                String?              @unique\n  emailVerified        DateTime?\n  image                String?\n  role                 Role                 @default(USER)\n  phoneNumber          String?\n  password             String?\n  // User location for emergency services\n  latitude             Float?\n  longitude            Float?\n  address              String?\n  // Profile completion tracking\n  profileCompleted     Boolean              @default(false)\n  accounts             Account[]\n  emergencyRequests    EmergencyRequest[]\n  safetyConfirmations  SafetyConfirmation[]\n  sessions             Session[]\n  // Rescue requests created by user\n  rescueRequests       RescueRequest[]      @relation(\"UserRescueRequests\")\n  // Rescue requests assigned to volunteer\n  volunteerAssignments RescueRequest[]      @relation(\"VolunteerAssignments\")\n  // Volunteer profile for location tracking\n  volunteerProfile     VolunteerProfile?\n  // Safe zones created by this user\n  createdSafeZones     SafeZone[]\n  // Resource nodes created by this user\n  createdResourceNodes ResourceNode[]\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\nmodel Alert {\n  id           String       @id @default(cuid())\n  title        String\n  message      String\n  disasterType DisasterType\n  latitude     Float        @default(15.3173)\n  longitude    Float        @default(75.7139)\n  radiusKm     Int          @default(5)\n  createdAt    DateTime     @default(now())\n\n  @@index([latitude, longitude])\n}\n\nmodel SafetyGuide {\n  id           String       @id @default(cuid())\n  disasterType DisasterType @unique\n  content      String\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n}\n\nmodel EmergencyRequest {\n  id          String          @id @default(cuid())\n  userId      String\n  phoneNumber String\n  latitude    Float\n  longitude   Float\n  createdAt   DateTime        @default(now())\n  status      EmergencyStatus @default(OPEN)\n  user        User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel SafetyConfirmation {\n  id          String   @id @default(cuid())\n  userId      String\n  phoneNumber String\n  createdAt   DateTime @default(now())\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nenum Role {\n  USER\n  VOLUNTEER\n  AUTHORITY\n}\n\nenum DisasterType {\n  FLOOD\n  EARTHQUAKE\n  FIRE\n  MEDICAL\n  BUILDING_COLLAPSE\n  OTHER\n}\n\nenum EmergencyStatus {\n  OPEN\n  RESOLVED\n}\n\n// Rescue request status for SOS system\nenum RescueStatus {\n  PENDING\n  ASSIGNED\n  IN_PROGRESS\n  COMPLETED\n  NO_VOLUNTEER\n}\n\n// Safe zone types for shelters\nenum SafeZoneType {\n  SHELTER\n  CAMP\n  HOSPITAL\n}\n\n// Risk levels for danger zones\nenum RiskLevel {\n  LOW\n  MEDIUM\n  HIGH\n}\n\n// Resource types for disaster response\nenum ResourceType {\n  BOAT\n  GENERATOR\n  WATER\n  FOOD\n  MEDICAL\n  OTHER\n}\n\n// Creator types for resources\nenum CreatorType {\n  VOLUNTEER\n  BUSINESS\n  AUTHORITY\n}\n\n// Rescue requests (SOS) from users in danger\nmodel RescueRequest {\n  id               String        @id @default(cuid())\n  userId           String?\n  user             User?         @relation(\"UserRescueRequests\", fields: [userId], references: [id])\n  volunteerId      String?\n  volunteer        User?         @relation(\"VolunteerAssignments\", fields: [volunteerId], references: [id])\n  status           RescueStatus  @default(PENDING)\n  message          String?\n  location         String?\n  latitude         Float?\n  longitude        Float?\n  disasterType     DisasterType? // Optional post-SOS detail\n  note             String? // Optional post-SOS note\n  searchRadiusUsed Float? // km radius that found the volunteer (2, 5, or 10)\n  // ML-assisted ETA prediction fields\n  etaMinMinutes    Int? // Minimum estimated arrival time\n  etaMaxMinutes    Int? // Maximum estimated arrival time\n  etaConfidence    String? // HIGH, MEDIUM, LOW\n  etaFactors       String? // JSON array of factors affecting ETA\n  escalatedAt      DateTime?\n  assignedAt       DateTime?\n  completedAt      DateTime?\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n\n  @@index([status])\n  @@index([volunteerId])\n}\n\n// Volunteer profile with live location tracking\nmodel VolunteerProfile {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  latitude  Float?\n  longitude Float?\n  available Boolean  @default(true)\n  updatedAt DateTime @updatedAt\n}\n\n// Safe zones (shelters, camps, hospitals) created by volunteers or authorities\nmodel SafeZone {\n  id        String       @id @default(cuid())\n  name      String\n  type      SafeZoneType\n  latitude  Float\n  longitude Float\n  capacity  Int?\n  createdBy String // User ID who created this zone\n  creator   User         @relation(fields: [createdBy], references: [id])\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  @@index([latitude, longitude])\n}\n\n// Resource nodes for disaster response (crowdsourced resources)\nmodel ResourceNode {\n  id           String       @id @default(cuid())\n  name         String\n  resourceType ResourceType\n  quantity     Int\n  latitude     Float\n  longitude    Float\n  createdBy    CreatorType\n  contactInfo  String?\n  userId       String // User ID who created this resource\n  creator      User         @relation(fields: [userId], references: [id])\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  @@index([latitude, longitude])\n  @@index([resourceType])\n}\n",
